// === Tab: mySketch ===
let currentSeed = 53;
let shapes = [];
let particles = [];
const numParticles = 4000;
let backgroundLines = []; 

function setup() {
  createCanvas(1200, 800);
  colorMode(HSB, 100, 100, 100);
  generateArt();
}

function generateArt() {
  randomSeed(currentSeed);
  background(360, 0, 100);

  // Clear previous elements
  shapes = [];
  particles = [];
  backgroundLines = [];

  // Create seed-based elements
  createBackgroundLines();
  createMainShapes();
  createGrainEffect();
  createDotsEffect();

  // Initialize particles
  for (let i = 0; i < numParticles; i++) {
    particles.push({
      x: random(width),
      y: random(height),
      size: random(1, 4),
      baseX: random(width),
      baseY: random(height),
      speed: random(0.3, 1.2)
    });
  }
}

function createBackgroundLines() {
  const numLines = int(random(25, 45));
  for (let i = 0; i < numLines; i++) {
    const x = random(width);
    const y = random(height);
    const angle = random(TWO_PI);
    const lineLength = width * random(5.5, 6.5);
    stroke(0, random(15, 40));
    strokeWeight(random(0.06, 1.8));
    push();
    translate(x, y);
    rotate(angle);
    line(-lineLength/2, 0, lineLength/2, 0);
    pop();
  }
}

function createMainShapes() {
  const numShapes = int(random(20, 50));
  const maxSize = random(5, 200);

  for (let i = 0; i < numShapes; i++) {
    const shape = {
      baseX: random(width),
      baseY: random(height),
      x: 0,
      y: 0,
      sides: int(random(3, 9)),
      size: random(maxSize/2, maxSize),
      rotation: random(TWO_PI),
      scaleFactor: random(0.3, 3),
      scaleAxis: random() < 0.5 ? 'x' : 'y',
      radiusX: 0,
      radiusY: 0,
      aberrationOffset: 0.8
    };

    // Set initial position
    shape.x = shape.baseX;
    shape.y = shape.baseY;
    shapes.push(shape);
  }
}

function draw() {
  background(360, 0, 100);

  // Draw interactive elements
  drawBackgroundElements();
  drawInteractiveShapes();
  drawInteractiveParticles();
  drawVignette();
  drawSeedInfo();
}
function createBackgroundLines() {
  var numLines = int(random(8, 25));
  for (let i = 0; i < numLines; i++) {
    backgroundLines.push({
      x: random(width),
      y: random(height),
      angle: random(TWO_PI),
      length: width * random(5.5, 6.5),
      strokeAlpha: random(15, 40),
      strokeWeight: random(0.06, 1.8)
    });
  }
}

function drawBackgroundElements() {
  for (let bgLine of backgroundLines) { // Changed variable name from 'line' to 'bgLine'
    stroke(0, bgLine.strokeAlpha);
    strokeWeight(bgLine.strokeWeight);
    push();
    translate(bgLine.x, bgLine.y);
    rotate(bgLine.angle);
    line(-bgLine.length/2, 0, bgLine.length/2, 0); // Now using p5.js line() function
    pop();
  }
}

function drawInteractiveShapes() {
  for (let shape of shapes) {
    // Update shape position based on mouse
    const mouseDist = dist((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))), shape.x, shape.y);
    const repulsionRadius = 300;

    if (mouseDist < repulsionRadius) {
      const force = p5.Vector.sub(createVector(shape.x, shape.y), createVector((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)))));
      force.setMag(map(mouseDist, 0, repulsionRadius, 8, 0));
      shape.x += force.x;
      shape.y += force.y;
    } else {
      // Return to base position
      shape.x = lerp(shape.x, shape.baseX, 0.1);
      shape.y = lerp(shape.y, shape.baseY, 0.1);
    }

    // Calculate scaling
    if (shape.scaleAxis === 'x') {
      shape.radiusX = shape.size * shape.scaleFactor;
      shape.radiusY = shape.size;
    } else {
      shape.radiusX = shape.size;
      shape.radiusY = shape.size * shape.scaleFactor;
    }

    // Draw chromatic aberration
    colorMode(RGB);
    noStroke();
    fill(255, 0, 0, 50);
    drawPolygon(shape.x, shape.y, shape.radiusX, shape.radiusY, shape.sides, shape.rotation);
    fill(0, 255, 0, 50);
    drawPolygon(shape.x, shape.y, shape.radiusX, shape.radiusY, shape.sides, shape.rotation);
    fill(0, 0, 255, 50);
    drawPolygon(
      shape.x + shape.aberrationOffset,
      shape.y + shape.aberrationOffset,
      shape.radiusX,
      shape.radiusY,
      shape.sides,
      shape.rotation
    );

    // Draw main shape
    colorMode(HSB);
    fill(0, 0, 0);
    drawPolygon(shape.x, shape.y, shape.radiusX, shape.radiusY, shape.sides, shape.rotation);
  }
}

function drawInteractiveParticles() {
  for (let particle of particles) {
    var mouseDist = dist((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))), particle.x, particle.y);
    var repulsionRadius = 150;

    if (mouseDist < repulsionRadius) {
      var force = p5.Vector.sub(createVector(particle.x, particle.y), createVector((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)))));
      force.setMag(map(mouseDist, 0, repulsionRadius, 5, 0));
      particle.x += force.x * particle.speed;
      particle.y += force.y * particle.speed;
    } else {
      // Return to base position
      particle.x = lerp(particle.x, particle.baseX, 0.05);
      particle.y = lerp(particle.y, particle.baseY, 0.05);
    }

    // Draw particle
    fill(0);
    noStroke();
    ellipse(particle.x, particle.y, particle.size);
  }
}

function drawPolygon(x, y, rx, ry, sides, rotation) {
  push();
  translate(x, y);
  rotate(rotation);
  beginShape();
  var angle = TWO_PI / sides;
  for (let a = 0; a < TWO_PI; a += angle) {
    vertex(cos(a) * rx, sin(a) * ry);
  }
  endShape(CLOSE);
  pop();
}

function createGrainEffect() {
  const numGrains = 150000;
  for (let i = 0; i < numGrains; i++) {
    fill(0, 0, 0, random(0.3, 1));
    noStroke();
    ellipse(random(width), random(height), random(0.3, 0.8));
  }
}

function createDotsEffect() {
  const numDots = random(50, 100);
  for (let i = 0; i < numDots; i++) {
    fill(0, 0, 0, random(0.1, 1));
    noStroke();
    ellipse(random(width), random(height), random(0.5, 6));
  }
}

function drawVignette() {
  const ovalRatio = 1.6;
  const vignetteStrength = 0.7;
  const vignetteSize = 1.0;

  push();
  scale(1, ovalRatio);
  let gradient = drawingContext.createRadialGradient(
    width/2,
    height/(2 * ovalRatio),
    height * 0.1 * vignetteSize,
    width/2,
    height/(2 * ovalRatio),
    height * vignetteSize
  );
  gradient.addColorStop(0, 'rgba(255, 255, 255, 0)');
  gradient.addColorStop(1, `rgba(0, 0, 0, ${vignetteStrength})`);
  drawingContext.fillStyle = gradient;
  drawingContext.fillRect(0, 0, width, height/ovalRatio);
  pop();
}

function drawSeedInfo() {
  fill(50);
  textSize(20);
  text(`Seed: ${currentSeed}`, 20, 30);
}

function keyPressed() {
  if (key === 'n' || key === 'b') {
    currentSeed += key === 'n' ? 1 : -1;
    generateArt();
  }
  if (key === 's') saveCanvas(`artwork_seed_${currentSeed}`, 'png');
}

function mouseMoved() {
  redraw(); // Continuous updates for interaction
}

